/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=organization, operation=search
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Search deals */
export type PipedriveV2OrganizationSearchParams = {
  resource: 'organization';
  operation: 'search';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * The search term to look for. Minimum 2 characters (or 1 if using exact_match).
 */
    term: string | Expression<string> | PlaceholderValue;
/**
 * Whether only full exact matches against the given term are returned. It is not case sensitive.
 * @default false
 */
    exactMatch?: boolean | Expression<boolean>;
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 100
 */
    limit?: number | Expression<number>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** A comma-separated string array. The fields to perform the search from. Defaults to all of them.
     * @default ["custom_fields","name","notes","address"]
     */
    fields?: Array<'address' | 'custom_fields' | 'name' | 'notes'>;
  };
};

export type PipedriveV2OrganizationSearchOutput = {
  custom_fields?: Array<string>;
  id?: number;
  name?: string;
  notes?: Array<string>;
  owner?: {
    id?: number;
  };
  result_score?: number;
  type?: string;
  visible_to?: number;
};

export type PipedriveV2OrganizationSearchNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2OrganizationSearchParams>;
  output?: Items<PipedriveV2OrganizationSearchOutput>;
};